using System;using System.Reflection;using LoopFive;
class FxQualityTests {
 static int count;static void A(bool b,string text){if(!b)throw new Exception(text);count++;Console.WriteLine("PASS "+text);}
 static float[] Impulse(float size){StudioReverb r=new StudioReverb();r.Configure(size,.35f);float[] data=new float[44100*4*2];for(int i=0;i<data.Length/2;i++)r.Tick(i==0?1:0,i==0?1:0,out data[i*2],out data[i*2+1]);return data;}
 static double Energy(float[] x,int first,int last){double e=0;for(int i=first;i<last;i++)e+=x[i]*x[i];return e;}
 static double Bin(float[] x,int bin){double re=0,im=0;for(int i=0;i<x.Length;i++){double p=2*Math.PI*bin*i/x.Length;re+=x[i]*Math.Cos(p);im-=x[i]*Math.Sin(p);}return Math.Sqrt(re*re+im*im);}
 static void Main(){try{float[] small=Impulse(.1f),large=Impulse(.85f);int dense=0;double stereo=0;for(int i=10000;i<50000;i+=2){if(Math.Abs(large[i])>1e-7)dense++;stereo+=Math.Abs(large[i]-large[i+1]);}A(dense>15000,"reverb tail is diffuse rather than sparse isolated echoes");A(stereo>.1,"mono input produces decorrelated stereo reverb");double tailSmall=Energy(small,44100*2,44100*4),tailLarge=Energy(large,44100*2,44100*4);A(tailLarge>tailSmall*10,"reverb size controls measurable decay duration");A(Energy(large,44100*6,44100*8)<Energy(large,44100,44100*3),"reverb tail decays without runaway feedback");
 FxProcessor fx=new FxProcessor();FxConfig c=new FxConfig{On=true,Type="DELAY",Mix=1};fx.Prepare(c,120,60,false);float[] buffer=(float[])typeof(FxProcessor).GetField("dl",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(fx);for(int i=0;i<buffer.Length;i++)buffer[i]=(float)Math.Sin(i*.12);typeof(FxProcessor).GetField("wp",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(fx,10000);MethodInfo read=typeof(FxProcessor).GetMethod("Read",BindingFlags.NonPublic|BindingFlags.Instance);double ec=0,el=0;for(int i=1;i<20;i++){double behind=500+i*.037,p=10000-behind;int at=(int)p;double ideal=Math.Sin(p*.12),linear=buffer[at]+(buffer[at+1]-buffer[at])*(p-at);float cubic=(float)read.Invoke(fx,new object[]{buffer,behind});ec+=Math.Abs(cubic-ideal);el+=Math.Abs(linear-ideal);}A(ec<el*.08,"cubic delay interpolation reduces sine reconstruction error over linear");Console.WriteLine("Interpolation errors: cubic="+ec+" linear="+el);
 int length=8192,bin=1733,alias=length-bin*3;float[] anti=new float[length],raw=new float[length];SmoothSaturator sat=new SmoothSaturator();for(int i=-8192;i<length;i++){float x=.65f*(float)Math.Sin(2*Math.PI*bin*i/length);float y=sat.Tick(x,18);if(i>=0){anti[i]=y;raw[i]=(float)Math.Tanh(x*18);}}double ratioAnti=Bin(anti,alias)/Bin(anti,bin),ratioRaw=Bin(raw,alias)/Bin(raw,bin);Console.WriteLine("Aliased third / fundamental: improved="+ratioAnti+" naive="+ratioRaw);A(ratioAnti<ratioRaw*.7,"antiderivative saturation reduces measured aliased harmonic relative to naive tanh");
 fx=new FxProcessor();c=new FxConfig{On=true,Type="DELAY",Mix=0};fx.Prepare(c,120,60,false);for(int i=0;i<512;i++){float l=.2f,r=.2f;fx.Tick(ref l,ref r,0);}c.Mix=1;fx.Prepare(c,120,60,false);float left=.2f,right=.2f;fx.Tick(ref left,ref right,0);A(left>.19f,"wet/dry control change ramps instead of an instantaneous full-scale jump");
 fx=new FxProcessor();c=new FxConfig{On=true,Type="CHORUS",Mix=1,Amount=.8f};fx.Prepare(c,120,60,false);double diff=0;for(int i=0;i<44100;i++){left=right=.2f*(float)Math.Sin(i*.1);fx.Tick(ref left,ref right,i/22050.0);diff+=Math.Abs(left-right);}A(diff>1,"three-voice chorus creates a stereo image from mono");
 Console.WriteLine("TOTAL "+count+" effect quality checks passed");}catch(Exception ex){Console.WriteLine("FAIL "+ex);Environment.ExitCode=1;}}
}
